            if x == y:
                continue
            if x > y:
                x, y = y, x
            groups[(x, y)].append(i)

        ans = 0

        for starts in groups.values():
            k = len(starts)
            for i in range(k):
                found = False
                for j in range(i + 1, k):
                    left = starts[i]
                    right = starts[j]
                    d = right - left

                    if d == 1:
                        continue
                    if d == 2 and A[left] != A[right]:
                        continue

                    ans += 1
                    found = True
                    break
                if found:
                    break

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
